/* 故事路由 / 独立资产 / 快照交接，不写入旧漫画或视频工程。 */
(()=>{const C=Cimora,M=ScriptStudio,E=C.E,KEY='cimora-script-studio-v1';let mounted=null,storageError='';
function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return M.initial();const s=JSON.parse(raw);if(s.version!==1||!Array.isArray(s.projects)||!Array.isArray(s.assets))throw Error('格式异常');return s;}catch{storageError='Could not read saved stories. Keep your browser data and export a backup of your current draft.';return M.initial();}}
function save(s){if(storageError){C.S.toast(storageError);return false;}try{localStorage.setItem(KEY,JSON.stringify(s));return true;}catch{C.S.toast('Storage is full. Export a project backup to keep your changes.');return false;}}
function download(text,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
function handoff(a,epId,target){const selected=a.outline.filter(e=>!epId||e.id===epId);if(!selected.length||selected.some(e=>!a.scripts[e.id]))throw Error('Complete the selected episode first. Exporting the whole story requires text for every episode.');if(target==='comic'){const raw=localStorage.getItem('cimora-comic-studio-v1');let s;if(raw){const parsed=JSON.parse(raw);if(!Array.isArray(parsed.projects)||!parsed.projects.every(ComicStudio.validProject))throw Error('Could not read the saved comic projects.');s=parsed;}else s=ComicStudio.initial();if(s.projects.length>=30)throw Error('The comic workspace has reached its 30-project limit. Export a backup first.');const p=M.toComic(a,epId);if(!ComicStudio.validProject(p))throw Error('The episode is too long for the comic editor. Transfer a smaller selection.');s.projects.push(p);s.active=p.id;localStorage.setItem('cimora-comic-studio-v1',JSON.stringify(s));location.hash='#/app/comic?project='+encodeURIComponent(p.id);return;}
const V=C.M.videoFlow,W=C.M.videoWorkspace;if(!V||!W)throw Error('The video workspace could not load. Refresh and try again.');const source=V.fromStory(a,epId);source.world=a.facts||'';source.genre=a.adoptedPlan?.genre||a.settings?.genre||'';source.audience=a.adoptedPlan?.audience||a.settings?.audience||'';source.episodes.forEach(e=>{e.text=M.bodyText(a,e.id);});source.text=source.episodes.map(e=>e.title+'\n'+e.text).join('\n\n');const c=V.create(source,{title:a.title+(epId?' · '+selected[0].title:''),duration:(a.outlineSettings?.minutes||3)*60});W.ensure(c).facts=a.characters.map(person=>[person.name,person.identity,person.background,person.relation].filter(Boolean).join(' · ')).join('\n\n');c.e.scriptAssetSource={type:'script-asset-snapshot',assetId:a.assetId,title:a.title,savedAt:a.savedAt,episodeIds:selected.map(e=>e.id),characters:M.clone(a.characters),original:a.original,text:M.episodeText(a,epId)};if(C.M.save()===false)throw Error('Could not save the video project. Export a story backup first.');C.M.remember(c);C.S.route('/app/video?project='+encodeURIComponent(c.p.id)+'&episode='+encodeURIComponent(c.c.id)+'&stage=1');}

C.storyAssetBridge={handoff};

function assetSection(){const s=load();return `<section class="ss-library-entry cm-panel"><div><span class="cm-kicker">STORY ASSETS</span><h2>故事资产</h2><p>${s.assets.length} 份已保存故事 · 原文、设定与分集内容一起保留</p></div>${C.link('查看 / 选用故事 →','/app/assets?type=scripts','cm-button primary')}${C.link('Story workspace','/app/script','cm-button ghost')}</section>`;}
function library(){const s=load();return `<div class="ss-workspace ss-library"><div class="cm-page-heading"><span class="cm-kicker">STORY ASSETS</span><h1>故事资产</h1><p>故事身份和剧情作用独立于视觉资产。选定整部或某集，复制来源快照开始新作品。</p></div><div class="ss-actions">${C.link('全部视觉资产','/app/assets','cm-button ghost')}${C.link('Story workspace','/app/script','cm-button primary')}</div>${storageError?`<p role="alert">${E(storageError)}</p>`:''}${s.assets.length?`<div class="ss-library-grid">${s.assets.map(a=>`<article class="cm-panel"><span class="cm-kicker">故事 · ${a.outline.length} 集</span><h2>${E(a.title)}</h2><p>${a.characters.map(c=>E(c.name)+(c.aliases?' / '+E(c.aliases):'')).join('、')||'尚未登记人物'}</p><p>${E(new Date(a.savedAt).toLocaleString('zh-CN'))} · 已保存快照</p><label>使用范围<select data-ss-asset-episode="${a.assetId}"><option value="">整部（每集都需有故事）</option>${a.outline.map(e=>`<option value="${e.id}">${E(e.title)}${a.scripts[e.id]?'':' · 尚未有故事'}</option>`).join('')}</select></label><details><summary>故事 / 身份 / 来源预览</summary><pre>${E(M.episodeText(a))}</pre><p>${E(a.characters.map(c=>c.id+' / '+c.name+' / '+c.identity+' / '+c.relation).join('\n'))}</p><p>来源：${E(a.sourceName)}，原文 ${M.count(a.original)} 字，${a.scope==='full'?'全文':a.scope==='chapter'?'所选章节':'所选片段'}。</p></details><div class="ss-actions"><button class="cm-button primary" data-ss-use="comic" data-asset="${a.assetId}">选用故事新建漫画 →</button><button class="cm-button ghost" data-ss-use="video" data-asset="${a.assetId}">选用故事新建视频 →</button></div><div class="ss-actions"><a class="cm-button ghost" href="#/app/script?project=${encodeURIComponent(a.id)}">继续编辑工程</a><button class="cm-button ghost" data-ss-download="json" data-asset="${a.assetId}">导出 JSON</button><button class="cm-button ghost" data-ss-download="txt" data-asset="${a.assetId}">导出 TXT</button></div></article>`).join('')}</div>`:`<div class="cm-panel"><h2>还没有故事资产</h2><p>先从灵感或已有内容整理一集，保存后即可在这里选用。不会把空稿伪装成已完成资产。</p>${C.link('开始故事创作 →','/app/script','cm-button primary')}</div>`}<p class="ss-help">复制新工程，不覆盖旧漫画、视频或草稿。故事后续修改不会自动同步已复制内容。</p><p id="ss-library-message" role="status"></p></div>`;}
const route=C.route;C.route=r=>{if(r.parts[0]==='app'&&r.parts[1]==='script')return '<div id="script-workspace" class="ss-workspace" aria-label="Story workspace"></div>';if(r.parts[0]==='app'&&r.parts[1]==='assets'&&r.params.get('type')==='scripts')return library();return route(r);};
const assets=C.pages.assets;C.pages.assets=r=>r.parts[2]?assets(r):assetSection()+assets(r);
const newPage=C.pages.new;C.pages.new=r=>`<div class="ss-video-source cm-panel"><div><strong>已有保存的故事？</strong><p>选择整部或某集，直接新建视频镜头方案；保留故事来源快照。</p></div>${C.link('选用故事资产 →','/app/assets?type=scripts&use=video','cm-button ghost')}</div>`+newPage(r);
const title=C.pageTitle;C.pageTitle=r=>r.parts[1]==='script'?'Story workspace':title(r);
const studio=C.studio;C.studio=c=>{const source=c.e.scriptAssetSource;return (source?`<section class="cm-panel ss-video-source"><div><strong>故事来源：${E(source.title||c.p.name)}</strong><p>已复制所选故事的独立快照；原故事后续修改不会自动覆盖当前视频。</p><details><summary>来源身份与版本</summary><p>${E(source.assetId)} · ${E(source.savedAt)}</p><p>${E(source.characters.map(x=>x.id+' / '+x.name+' / '+x.identity).join('；'))}</p></details></div>${C.link('查看故事资产','/app/assets?type=scripts','cm-button ghost')}</section>`:'')+studio(c);};
const after=C.afterRender;C.afterRender=r=>{after(r);document.body.classList.toggle('cimora-script-workspace',r.parts[1]==='script'||r.parts[1]==='comic'&&!!document.getElementById('script-workspace'));mounted?.destroy();mounted=null;if(r.parts[1]==='script'){const s=load(),wanted=r.params.get('project');if(wanted&&!s.projects.some(p=>p.id===wanted)){const host=document.getElementById('script-workspace');if(host)host.innerHTML='<p role="alert">Story not found. Return to My Projects.</p>';return;}if(wanted&&s.projects.some(p=>p.id===wanted)){s.active=wanted;const selected=s.projects.find(p=>p.id===wanted);if(selected.agent&&selected.storyChapters?.some(c=>c.id===r.params.get('chapter')))selected.agent.selectedChapter=r.params.get('chapter');if(selected.agent?.phase==='planning'&&['overview','characters','story-outline','chapters'].includes(r.params.get('tab')))selected.agent.planningTab=r.params.get('tab');save(s);}const host=document.getElementById('script-workspace');if(host){mounted=mountScriptStudio(host,{...storyWritingBridge(host),load:()=>s,save,download,handoff,exportStory:window.ExportCenter?project=>ExportCenter.chooseStory(project):undefined,newIntent:r.params.get('intent')==='new'});const crumb=document.querySelector('.cm-breadcrumb strong');if(crumb)crumb.textContent='Story workspace';}return;}if(r.parts[1]==='assets'&&r.params.get('type')==='scripts'){document.querySelectorAll('[data-ss-use]').forEach(b=>b.onclick=()=>{try{const s=load(),a=s.assets.find(x=>x.assetId===b.dataset.asset),select=[...document.querySelectorAll('[data-ss-asset-episode]')].find(x=>x.dataset.ssAssetEpisode===a.assetId);handoff(a,select.value,b.dataset.ssUse);}catch(e){document.getElementById('ss-library-message').textContent=e.message;C.S.toast(e.message);}});document.querySelectorAll('[data-ss-download]').forEach(b=>b.onclick=()=>{const a=load().assets.find(x=>x.assetId===b.dataset.asset);download(b.dataset.ssDownload==='json'?M.exportJSON(a):M.exportText(a),a.title+(b.dataset.ssDownload==='json'?'-故事工程.json':'-故事.txt'),b.dataset.ssDownload==='json'?'application/json':'text/plain');});}};
})();
